mapper.select:
SELECT m.*, p.id AS p_id, p.NAME AS p_name, p.remark AS p_remark, IFNULL( me.endpointNum, 0 ) AS endpointNum, IFNULL( me.assetNum, 0 ) AS assetNum, IFNULL( msg.alertNum, 0 ) AS alertNum, IFNULL( sta.starred, 0 ) AS starred FROM monitor_module m LEFT JOIN monitor_project p ON m.project_id = p.id LEFT JOIN ( SELECT module_id, count( 1 ) AS endpointNum, count( DISTINCT asset_id ) AS assetNum FROM monitor_endpoint GROUP BY module_id ) me ON m.id = me.module_id LEFT JOIN ( SELECT module_id, count( 1 ) AS alertNum FROM alert_message_active WHERE module_id IS NOT NULL GROUP BY module_id ) msg ON m.id = msg.module_id LEFT JOIN ( SELECT IF(COUNT(1) > 0, 1, 0) AS starred,tid FROM sys_user_starred WHERE TYPE = "module" AND uid = #{params.uid} GROUP BY tid) sta ON m.id = sta.tid
m.id IN
#{id}
AND m.project_id IN
#{projectId}
AND locate(#{params.name} , m.name)
AND
sta.starred = #{params.starred}
sta.starred IS NULL
ORDER BY m.id
